import React, { useEffect, useState } from "react";
import API from "../api/api";

function Results() {
  const [results, setResults] = useState({});

  useEffect(() => {
    API.get("/api/results/1").then((res) => {
      setResults(res.data);
    });
  }, []);

  return (
    <div>
      <h2>Results</h2>
      {Object.entries(results).map(([name, count]) => (
        <p key={name}>
          {name}: {count} votes
        </p>
      ))}
    </div>
  );
}

export default Results;
